// Company procedures are proposed HATCO defaults, not assertions of client approval.
export function applyHatco(p,humain=false,seed={}) {
  p.preset=humain?'humain':'hatco';
  Object.assign(p.fields,{
    projectName:humain?'HUMAIN':'HATCO Company BIM Standard',projectCode:humain?'HUMAIN':'HATCO',
    documentTitle:humain?'HUMAIN — HATCO Post-Contract BIM Execution Plan':'HATCO BIM Standard & Project BEP Guideline',
    documentCode:humain?'HUMAIN-HAT-ZZ-ZZ-BEP-BIM-00001':'HAT-BIM-STD-001',revision:'P01',
    description:humain?'HATCO contractor BIM delivery for HUMAIN. JLL represents the owner and WSP represents the consultant. Exact work packages and external coordination boundaries require confirmation against the appointment.':'Company baseline for BIM production, coordination, quality control and information delivery across HATCO contracting projects.',
    contractor:'HATCO',client:humain?'Owner represented by JLL — legal entity to be confirmed':'Project appointing party — confirm at mobilization',consultant:humain?'WSP':'Project consultant — confirm at mobilization',
    preparedBy:'HATCO BIM function',checkedBy:'HATCO BIM Manager — named checker at issue',approvedBy:'HATCO Project Manager — approval pending',
    issuePurpose:'Proposed company standard / project review — not yet approved',informationRole:'Pending confirmation',designResponsibility:'Pending confirmation',
    coordinationScope:'HATCO coordinates its appointed works and assigned interfaces. External federation leadership, review authority and responsibility limits shall be confirmed in the project appointment.',
    exclusions:'No transfer of design liability through clash review. Fabrication, 4D, cost modelling, COBie, asset tagging and surveys are conditional uses, enabled only when the project scope requires them.',
    originatorCode:'HAT',namingPattern:'PROJECT-ORIGINATOR-VOLUME-LEVEL-TYPE-ROLE-NUMBER',drawingStrategy:'Discipline models',
    units:'Length: mm; elevation: m; area: m²; volume: m³',loinSystem:'Purpose / milestone / element matrix: geometry, data and documents',
    classification:'HATCO discipline and system codes internally; external classification scheme is project-specific',modelSizeLimit:'250 MB review trigger; split after performance assessment and BIM Manager agreement',
    authoringProcedure:'Use controlled HATCO templates and shared parameters; approved coordinate source; pinned links; discipline worksets; controlled documentation and export views; weekly model health review; checked exchanges.',
    coordinationCycle:'Weekly: exchange before federation; review and meeting; verified issue closure',issuePlatform:'Controlled issue register in the approved project platform',
    qaFrequency:'Author self-check, weekly model health check, independent check before every exchange',
    warningPolicy:'Zero unresolved critical warnings affecting model integrity or deliverable accuracy; other warnings logged with owner, justification and due date.',
    reviewWorkflow:'Author self-check → discipline technical check → HATCO BIM compliance and interface review → HATCO authorization → Document Control transmittal → designated project review / acceptance.',
    suitabilitySystem:'Internal: WIP / Coordination / Review / Authorized issue / Record. Map to client codes before formal exchange.',
    backupLocation:'HATCO IT-managed secondary repository, separate from the production CDE',backupFrequency:'Daily backup; weekly full recovery point; monthly restore test',retention:'Working recovery points: 30 daily and 12 monthly; formal records retained for the contract retention period, to be confirmed',
    asBuiltMethod:'Update from verified site redlines, approved changes and survey evidence; retain element identity and traceable source records; independent discipline check before submission.',asBuiltAccuracy:'Use element-specific survey / installation acceptance limits approved for the project; record method, coverage and measured deviation.',
    ...seed
  });
  const notes={
    overview:`APPLICATION AND CONTROL\nThis baseline defines HATCO's proposed internal working procedures. The BIM Manager maintains the master; project copies retain its version and record deviations. It is not evidence of HATCO management or client approval.\nAt mobilization, copy the standard, complete project-only decisions, review against the appointment and information requirements, then obtain the designated approvals. Client and contractual requirements take precedence; log conflicts and agree a project deviation rather than silently changing the company master.\nThe supplied Northwest Transport Hub Word BEP informs the section structure and procedural coverage only. Its organization names, approvals, contract dates, coordinates and code lists do not apply here.`,
    scope:`RESPONSIBILITY BOUNDARIES\nHATCO task teams own the accuracy and technical content of information they produce. Coordination review identifies interfaces and does not authorize a design change. Refer changes to the responsible engineer through the agreed RFI / technical submittal route.\nMaintain a package interface register: work package, originating designer, HATCO production scope, installation party, review party, inputs, outputs and exclusions. Confirm responsibilities for openings, supports, builder's work, specialist equipment, external utilities and existing services before production.\nDo not represent HATCO as lead appointed party solely because it federates models. Confirm the appointment and information management responsibility matrix.`,
    references:`REFERENCE CONTROL\nMaintain document identifier, title, revision, issue date, issuer, status and controlled location for the appointment, EIR, AIR, project information standard, survey/URS, design models, approved programme and handover requirements.\nDocument Control checks superseded references before each exchange. The BIM Manager records impact, affected models and required response when a reference changes. Missing project inputs remain open decisions; they must not be recorded as approved.\nInformative guidance: https://imiframework.org/ and UK BIM Framework Guidance Part 2, Edition 6 (2021). Confirm applicable editions and any national annex in the appointment. HATCO naming examples below are company defaults, not universal ISO-mandated codes.`,
    governance:`GOVERNANCE\nProject Manager: accountable for resources, scope decisions and internal issue authorization. BIM Manager: owns the BEP, information standards, QA gates, delivery consolidation and approved deviations. Discipline Lead: accountable for technical correctness. BIM Coordinator: federates checked models, runs tests and verifies issue closure. Model Author: produces and self-checks information. Document Controller: checks identifiers, revisions and transmittals. IT: controls access, backups and recovery.\nIdentify a named deputy for each critical role at mobilization. Authors must not provide the sole independent approval for their own issue. Record reviewer, date, outcome and evidence. Escalate overdue interface decisions to the Project Manager at the weekly coordination meeting.`,
    uses:`OBJECTIVES AND MEASURES\nRequired baseline uses: coordinated model production, model-derived drawings, interface review, QA/QC, delivery planning and verified record information within the appointment.\nReport weekly: due versus issued deliverables; rejected submissions and causes; unresolved critical issues; overdue issues by owner; models passing exchange QA. Count an issue as closed only after independent verification against an identified model revision.\nConditional uses remain Pending until their scope, responsible party, input, output and acceptance method are agreed. Do not activate a feature merely to make a completeness score higher.`,
    cde:`CDE WORKFLOW\nWIP is restricted to the producing task team. Shared information has passed team checks and carries its permitted use. Published information follows the project authorization / acceptance route. Archive retains superseded versions and the audit trail. Folder names alone do not constitute a complete approval workflow.\nUse 01_WIP, 02_SHARED, 03_PUBLISHED and 04_ARCHIVE as internal folder defaults where the platform does not provide equivalent states. Document Control maps these to the project platform.\nEach exchange carries identifier, title, revision, status, author, checker and transmittal reference. Never overwrite an issued version without version history. A cloud synchronization is not automatically a publish or formal submission; check the recipient-visible version before issuing its link.`,
    information:`EXCHANGE PROCEDURE\n1. Freeze the exchange list and input revisions. 2. Author self-checks. 3. Discipline Lead checks technical information. 4. BIM Coordinator checks naming, coordinates, scope and completeness. 5. Document Control validates metadata and issues the transmittal. 6. Record recipient response and required corrections.\nFor NWC export, use the controlled HAT-COORD-3D-EXPORT view, show all required model geometry and worksets, exclude annotations and linked models, and use the approved coordinate setting. Inspect the output extents, units and sample elements in federation. Do not assume opening all worksets alone makes all elements visible.\nExport each source model separately. Deliver NWD for a self-contained review snapshot and maintain NWF with its referenced NWC inputs for ongoing federation. IFC exchanges require project-agreed schema and sample validation of location, categories, properties and identifiers.`,
    security:`ACCESS AND RECOVERY\nUse named accounts, least privilege and MFA where supported. Remove leavers promptly and review team permissions monthly. Do not place credentials or sensitive site access/security details inside broadly shared models. Public preview links require a review of the actual snapshot and intended audience.\nIT monitors daily backup success and tests a representative restore monthly. Record restored file, recovery point, elapsed recovery time and checker. Proposed internal targets: no more than one working day of lost data and restoration within one working day; validate capacity at project mobilization.\nVersion history is useful but does not replace an independently recoverable backup. Stop synchronization after suspected corruption, isolate the affected copy, notify IT and BIM Manager, restore to a separate location and validate before replacing production.`,
    software:`SOFTWARE CONTROL\nAgree authoring major version and build, add-ins, exchange exporters and recipient tools before model creation. Do not upgrade a live project unilaterally. Test a copy, validate outputs and obtain project agreement before changing versions.\nThe company baseline uses Revit for building models, Navisworks Manage for federation and clashes, and spreadsheets for registers. Civil/survey tools are added for appointed civil scope. Product versions and CDE are project inputs; the transport-hub reference's versions are not automatically HUMAIN versions.`,
    breakdown:`MODEL SEGREGATION\nSplit first by production responsibility and discipline, then facility and zone where file performance, package boundaries or sequencing justify it. Do not mix another party's authored scope into HATCO source models. Use linked design references.\nDefault discipline codes: ARC architecture; STR structure; HVC HVAC; PLB plumbing/drainage; FPR fire protection; ELE electrical power/lighting; ELV low-current; CIV civil; BIM federation/reference. Register only disciplines actually appointed.\n250 MB is a review trigger from the reference's model strategy, adopted here as a proposed internal target; it is not a software limit. Investigate links, imported geometry, family complexity and warnings before splitting. Record new file identifiers, boundaries and affected TIDP rows after a split.`,
    naming:`CONTAINER NAMING\nUse uppercase ASCII codes and hyphens between fields, no spaces, no FINAL/LATEST suffixes, and a five-digit sequence unique within the other fields. Keep revision and suitability in controlled metadata unless the project expressly requires filename suffixes. HAT is the proposed internal HATCO originator code; external codes must match the client register.\nDefault example: HUMAIN-HAT-B01-L01-MOD-HVC-00001.rvt. This is illustrative, not an approved HUMAIN identifier. Match sheet numbers to the document register and exported PDF basename. Never infer room, building or level codes from this example.\nFAMILY: HAT-DISC-CATEGORY-DESCRIPTION; example HAT-HVC-MECH_EQ-AHU. TYPE: descriptive type plus distinguishing capacity or dimensions, e.g. AHU-12000LS; use 600x300 for rectangular duct sizes in mm. Do not put instance asset IDs into family names. Preserve supplier identity in manufacturer/model properties.\nVIEWS: HAT-PURPOSE-DISC-LEVEL-ZONE-DESCRIPTION, e.g. HAT-SDW-HVC-L01-B01-VENTILATION. PURPOSE values WIP, SDW, COORD, ASB. VIEW TEMPLATES: HAT-VT-DISC-PURPOSE-SCALE, e.g. HAT-VT-HVC-SDW-100.\nWORKSETS: 00_SHARED_LEVELS_GRIDS; 01_LINK_URS; 02_LINK_ARC; 03_LINK_STR; 10_HVC; 11_PLB; 12_FPR; 13_ELE; 14_ELV. Add numbered link/system worksets only for visibility or ownership needs; never one workset per user.\nPARAMETERS: HAT_BrowserGroup, HAT_BrowserDiscipline, HAT_BrowserPurpose, HAT_SystemCode, HAT_AssetID, HAT_DataStatus. Shared-parameter GUIDs and data types come from one BIM Manager-controlled definition file; do not recreate the same name with a different GUID. Use native Revit parameters where suitable.\nMATERIALS: HAT-DESCRIPTION-GRADE-FINISH. SYSTEMS: DISC-SYSTEMCODE-SEQUENCE, e.g. HVC-CHWS-001. ROOM/SPACE IDs follow architectural references; keep numbers stable and reconcile linked room changes.`,
    coordinates:`COORDINATE SETUP AND AUDIT\nObtain the authorized survey/URS with coordinate reference system, horizontal datum, units, vertical datum, benchmark, true north and issue revision. No zero rotation or assumed sea level is acceptable as a substitute for these project inputs.\nTest a copy, establish the shared-coordinate relationship using the approved workflow, pin links and verify at least three non-collinear control points plus a height benchmark. Record expected and observed coordinates and differences in a coordinate audit.\nCheck internal origin, project base point and survey point separately. Equal displayed point values alone do not prove correct federation. Validate exported NWC/IFC placement as well as native links. Never move a model to visually fit without an approved transform record.\nLevels and grids follow the authorized source; monitor changes and resolve notifications. Show drawing lengths in mm (whole numbers), levels in m (3 decimals), areas and volumes to 2 decimals. Display rounding does not define survey acceptance tolerance.`,
    loin:`INFORMATION NEED\nUse the matrix for each system and milestone: purpose, geometric extent, required properties, supporting documents, producer and validation. Avoid a blanket LOD 400/500 promise for every element. Record verification status independently from geometric detail.\nCoordination geometry includes insulation, necessary supports, access envelopes, penetrations and installation zones where required for the interface. Author maintenance envelopes as recognizable clearance objects, not actual equipment solids.\nOnly add detail that supports the agreed use. At procurement, validate approved type and performance. At handover, validate installed asset identity and linked records. A more detailed model does not automatically mean site verification.`,
    authoring:`REVIT WORKING PROCEDURE\nStart from the controlled HATCO template; complete the landing view, model ID, scope, units, browser parameters and issue reference. Open through the agreed worksharing route; create a fresh local copy where the local-central workflow requires one. Do not detach a production model for normal collaboration.\nSynchronize at sensible intervals (target 30 minutes and before breaks/close), relinquish owned elements when leaving, and use element borrowing. Coordinate maintenance with active users. Audit and compact only under the BIM Manager's maintenance procedure, with a recovery copy. Review purge selections; never purge blindly before every issue.\nKeep external references linked and pinned on dedicated worksets. Avoid exploded CAD, unmanaged imports, unnecessary in-place families and duplicate elements. Place services in correct categories/systems with correct connectors and elevations.\nBrowser organization: purpose → discipline → level/zone using controlled parameters. Documentation views use approved view templates; working views must not drive formal sheets. Use model-derived dimensions and tags, agreed lineweights and readable annotation; provide enlarged plans/sections in congested areas.\nTitle blocks contain project, parties, drawing identifier/title, scale, revision, status, author/checker and issue date. Populate controlled parameters, including revision schedules. Check clipping, view range, matchlines, references, key plan and legibility before PDF issue.`,
    quality:`QUALITY GATES\nGate 1: author checks geometry and data. Gate 2: independent discipline technical check. Gate 3: BIM standards and interface check. Gate 4: Document Control transmittal check. A failed mandatory check prevents exchange until corrected or a documented exception is authorized.\nCritical failures include wrong coordinates, missing required scope, duplicate issued identifiers, invalid links, misleading revision/status and unresolved interfaces that prevent the intended use. Weekly warning totals are trends, not automatic acceptance.\nQA evidence includes model identifier/revision, tool/version, date, checker, check result, issue reference and closeout evidence. Inspect PDF drawings visually as well as model reports.`,
    coordination:`FEDERATION AND CLASHES\nMaintain one controlled NWF test file per agreed federation scope. Record every source filename, revision and exchange date. Reject untraceable or mispositioned inputs before running tests. Use property-based search sets for repeatable discipline/system selection.\nRun hard clashes at 0 mm initially to avoid hiding small intersections; triage modelling noise with documented rules. Clearance values come from approved equipment, access and installation requirements, not an arbitrary global distance. Test insulation and maintainability explicitly.\nExclude intended connections and duplicate reference geometry only by an auditable rule. Cross-model tests and within-model QA are separate: do not globally discard same-file clashes and thereby lose internal coordination checks.\nGroup related results by location/system/root cause. Each issue records model revisions, element IDs, viewpoint, description, priority, owner, due date and proposed action. Workflow: Open → Assigned → In progress → Ready for verification → Closed; Accepted exception requires approver and justification.\nCritical: safety, inaccessible maintenance, blocked installation or major interface; escalate the same working day. Major: affects coordination/package delivery; agree action before next exchange. Minor: documentation or low-impact detail; resolve by the affected issue. Never close solely because a source model disappeared.`,
    meetings:`MEETING CYCLE\nHold weekly coordination after federation. Proposed internal sequence: models shared one working day before the meeting; coordinator publishes issues before the meeting; minutes issued within one working day afterwards. Set actual weekdays/time at mobilization.\nAgenda: source revisions and coverage; prior overdue actions; critical interfaces; design RFIs; next delivery gates; owners and dates. Review major reference-model changes with affected disciplines before adopting them as the new coordination basis.\nMaintain one issue register; meeting minutes reference issue IDs rather than creating a second disconnected action list. Escalate unresolved ownership to the Project Manager.`,
    delivery:`TIDP / MIDP\nEach task team prepares its TIDP before production. HATCO consolidates appointed information packages into its delivery plan; overall project MIDP leadership depends on the appointment.\nRequired register fields: unique document/model identifier, title, facility/zone, discipline, producer, reviewer, milestone, planned issue, forecast issue, actual issue, revision, status, format, dependencies and acceptance evidence. Keep the original baseline when forecasts change.\nCalculate on-time issue against the approved planned date; separately track acceptance and resubmissions. A file upload is not acceptance. Review dependencies and overdue outputs weekly, with recovery owner and forecast. Do not invent contractual dates to fill a template.`,
    fourD:`CONDITIONAL 4D PROCEDURE\nActivate only after confirming programme owner, tool, activity IDs, update cycle and deliverable. Link stable model groups to approved activity IDs and check unlinked/duplicate allocations. Validate sequence, temporary works and access with Planning and Construction. Record programme and model revisions in every simulation.`,
    fiveD:`CONDITIONAL QUANTITY / COST PROCEDURE\nAgree measurement rules, inclusions, exclusions, units and classification with the QS before extraction. Validate sample quantities against drawings and specifications; document non-modelled allowances and duplicate scope. Model quantities alone are not approved payment quantities. Cost-linking requires the agreed cost codes and scope mapping.`,
    existing:`EXISTING CONDITION PROCEDURE\nRecord survey date, control, accuracy, coverage and limitations. Compare survey/point cloud with the reference grid before use. Unknown buried services require the approved verification procedure; absence from a model is not evidence of absence on site. Record confidence and unresolved areas.`,
    fabrication:`FABRICATION PROCEDURE\nOnly the appointed specialist issues fabrication information. Agree interfaces, tolerances, approved equipment data and construction release before spool or fabrication exports. Keep a traceable mapping to coordinated model revisions. Fabrication approval follows the technical review process; clash-free status alone does not authorize manufacture.`,
    visualization:`VISUALIZATION PROCEDURE\nIdentify purpose, audience and source revision. Label illustrative content and avoid showing unapproved design as construction-approved. Remove sensitive information before external presentation. Obtain required project consent for public distribution.`,
    asbuilt:`RECORD INFORMATION\nSite engineers maintain dated redlines linked to location and approved change/RFI. Authors update records progressively, not only at closeout. Verify concealed services before covering when required by the inspection plan.\nRecord who verified each package, evidence, survey method, accuracy and unresolved limitations. Verify both service ends, offsets, levels and routes as relevant. Do not relabel an unverified construction model as as-built. Discipline Leads reconcile model, drawings and installed asset register before issue.`,
    assets:`CONDITIONAL ASSET DATA\nFor maintainable assets collect stable asset ID, system, space/location, manufacturer, model, serial number, installation/commissioning date, warranty and O&M reference when required by AIR. Define each property's data type, units, allowed values and responsible supplier before procurement.\nUse staged completeness checks: approved type data at procurement, serial/location at installation, commissioning and warranty at handover. Report blanks, duplicate IDs and broken document links; never fabricate serial numbers or dates.`,
    cobie:`CONDITIONAL COBIE\nConfirm the exact required schema/version, worksheets, client picklists and data drops before enabling COBie. Map Revit/shared parameters to the approved schema. Validate unique keys, cross-sheet references, required values and external document links, plus sample records with the receiving asset team. Do not promise COBie merely because Excel is available.`,
    tagging:`CONDITIONAL TAGGING\nUse the approved project asset identification scheme. Keep model object, physical label and asset database IDs identical and unique. Confirm label material, location and maintainability with the client before production. Verify tags on site and record replacements without silently reassigning an old identifier.`,
    handover:`HANDOVER GATE\nDeliver verified native models, agreed open formats, record PDFs, drawing/model index, asset data where appointed, QA evidence and change/issue disposition. Link approved O&M and commissioning documentation to the correct assets.\nCheck that the receiving team can open files and resolve references using the agreed tools. Record outstanding items and acceptance response. Acceptance is by the contractually designated party; internal HATCO approval is a separate step.\nFreeze an issued archive with transmittals, source revisions, software versions and acceptance records. Transfer archive custody to the nominated owner and retain HATCO records according to the confirmed retention requirement.`,
    appendices:`SUPPORTING SCHEDULES\nThe responsibility, naming, LOIN, exchange, delivery, clash and QA tables within this BEP form the baseline schedules. Project-specific survey/URS, approval records, detailed MIDP/TIDPs and client requirements must be linked as controlled attachments when received.\nAn appendix register entry is not proof of an attached or approved file. Show missing project documents as Not received; do not copy attachment links or logos belonging to the source transport-hub project.`
  };
  Object.assign(p.notes,notes);
  p.appliedTemplates=[{id:'hatco-company-v1',name:'HATCO Company BIM Standard',type:'company',version:'1.0',sourceReference:'Supplied Northwest Transport Hub Word BEP; adapted company procedures',mode:'built-in',appliedAt:new Date().toISOString()}];
  p.lists.parties=[{name:'HATCO',role:'Contractor',code:'HAT (internal proposed)',responsibility:'Appointed model production, coordination and delivery'}];
  if(humain)p.lists.parties.push({name:'JLL',role:'Owner representative',code:'JLL',responsibility:'Owner representation; delegated review/acceptance authority to be confirmed'},{name:'WSP',role:'Consultant representative',code:'WSP',responsibility:'Consultant review within confirmed appointment'});
  p.lists.namingFields=[['Project','Client project code; HUMAIN is a provisional readable default','HUMAIN'],['Originator','HAT internal; client-mapped codes for other organizations','HAT'],['Volume','B01 etc. from project building register; ZZ multiple; XX not applicable','B01'],['Level','L01 etc. from project level register; ZZ multiple; XX not applicable','L01'],['Type','MOD model; DRW drawing; BEP plan; RPT report; SCH schedule','MOD'],['Role','ARC, STR, HVC, PLB, FPR, ELE, ELV, CIV, BIM','HVC'],['Number','00001–99999; unique within the preceding fields','00001']].map(([field,codeList,example],i)=>({order:String(i+1),field,codeList,example}));
  p.lists.software=p.lists.software.filter(x=>!x.use.includes('4D'));
  p.lists.references=p.lists.references.filter(x=>x.code!=='REFERENCE-BEP');
  p.lists.references.push({title:'HATCO Company BIM Standard — proposed baseline',code:'HAT-BIM-STD-001',revision:'P01',status:'For review',source:'Built-in company baseline; management approval pending'});
  p.lists.team=['BIM Manager','BIM Coordinator','Discipline Lead','Document Controller','Project Manager'].map(role=>({name:'Named appointee at mobilization',organization:'HATCO',role,email:''}));
  p.lists.responsibilities.push(...[
    ['Authorize HATCO information issue','BIM Manager','Project Manager','Discipline Leads','Document Controller'],['Control identifiers and transmittals','Document Controller','Project Manager','BIM Manager','Recipients'],['Backup and restore verification','IT Administrator','IT Manager','BIM Manager','Project Manager'],['Verify installed record information','Site Engineer','Discipline Lead','BIM Coordinator','Document Controller'],['Approve technical design changes','Appointed design authority','Appointed design authority','HATCO Discipline Lead','Affected task teams']
  ].map(([activity,responsible,accountable,consulted,informed])=>({activity,responsible,accountable,consulted,informed})));
  p.lists.exchanges=[['Checked discipline models','Weekly coordination','HATCO discipline teams','HATCO BIM Coordinator','RVT / NWC'],['Federated review and issues','Weekly coordination','HATCO BIM Coordinator','Affected project reviewers','NWD / PDF / issue register'],['Shop drawing submission','Approved TIDP dates','HATCO Document Control',humain?'WSP via agreed review route':'Designated project reviewer','PDF / native if appointed'],['Verified record package','Handover gate','HATCO Document Control','Designated acceptance authority','RVT / IFC if required / PDF / data']].map(([exchange,milestone,sender,receiver,format])=>({exchange,milestone,sender,receiver,format,status:'Planned'}));
  p.lists.models=[];
  p.lists.loin=[['Services','Coordination','Actual routes, sizes, insulation, access envelopes and key supports','System, type, size, level and production status','Coordinated plans and interface sections'],['Equipment','Procurement','Approved dimensions, connections and maintenance envelope','Approved manufacturer, model and performance','Approved equipment submittal'],['Openings / supports','Before construction release','Coordinated size, position and support/interface geometry','Host, service, owner and approval reference','Reviewed builder’s work / support details'],['Maintainable equipment','Handover','Verified installed position and extent','Asset identity, location and AIR properties if required','Site verification, O&M and commissioning references']].map(([element,milestone,geometry,information,documentation])=>({element,milestone,geometry,information,documentation,responsible:'Appointed discipline / specialist; HATCO coordination'}));
  p.lists.milestones=['Mobilization','First coordinated exchange','Construction package release','Verified handover'].map(name=>({name,gate:name,date:'',output:'Checked information and approval evidence for this gate'}));
  p.lists.deliverables=[['BEP and project decisions','HATCO BIM Manager','PDF','Project requirements mapped; project-only decisions resolved before issue'],['Task / master delivery schedules','HATCO Information Manager','XLSX / PDF','Unique IDs, owners, dependencies and agreed dates'],['Checked models and coordinated drawings','HATCO Discipline Leads','RVT / NWC / PDF','QA gates passed; affected critical issues resolved'],['Federation and issue report','HATCO BIM Coordinator','NWD / issue register','Traceable inputs, assigned issues and verification evidence'],['Verified record package','HATCO Discipline Leads','RVT / PDF / agreed exchanges','Site evidence reconciled; project acceptance recorded']].map(([title,producer,format,acceptance])=>({title,producer,date:'',format,acceptance}));
  p.lists.clashes=[['Structure vs services','Structural solids','MEP services including insulation','Hard','0 mm initial detection'],['Architecture vs services','Walls, ceilings and doors','MEP services','Hard','0 mm initial detection'],['Services vs services','One service system','Other service systems','Hard','0 mm initial detection'],['Maintenance / access','Equipment access envelopes','All relevant physical geometry','Clearance','Equipment-specific approved envelope; do not add clearance twice'],['Duplicate geometry','Discipline physical geometry','Same discipline physical geometry','Duplicate','Investigate duplicate instances'],['Openings and interfaces','Service penetrations','Approved openings / hosts','Workflow','Verify approved size, position and firestopping interface']].map(([name,setA,setB,type,tolerance])=>({name,setA,setB,type,tolerance,owner:'HATCO BIM Coordinator + responsible Discipline Lead'}));
  p.lists.qaChecks.push(...[['Export scope and links','Every exchange','No missing appointed scope or duplicated linked models','Export-view checklist / federation sample'],['Drawing legibility and metadata','Every issue','Identifiers match register; tags/dimensions readable; revisions correct','Independent PDF review'],['Critical coordination issues','Before package release','Resolved and verified or formally dispositioned by designated authority','Issue closure record'],['Backup restoration','Monthly','Restored sample opens and content is verified','IT restore log']].map(([check,frequency,acceptance,evidence])=>({check,frequency,checker:'HATCO responsible checker',acceptance,evidence})));
  p.lists.assetRequirements=[{asset:'Maintainable equipment (if AIR requires)',property:'Asset ID, system, location, manufacturer, model, serial, commissioning date, warranty, O&M reference',source:'Approved supplier and verified site records',milestone:'Procurement → installation → handover',format:'Client-approved schema',responsible:'Discipline Lead / supplier'}];
  p.lists.decisions=[
    ['Company baseline approval','HATCO management to approve the proposed procedures, codes and internal targets.','HATCO BIM Manager'],
    ['Appointment and parties','Confirm legal owner, scope, design responsibility and delegated JLL/WSP authority; do not assume HATCO is lead appointed party.','HATCO Project Manager'],
    ['Client information requirements','Obtain EIR/AIR, required standards and client naming/status code lists; map internal defaults.','HATCO BIM Manager'],
    ['Project identifiers and breakdown','Confirm official project/document/originator codes, model register, facility/zone/level codes. Examples are provisional.','HATCO Document Controller'],
    ['Survey and coordinates','Obtain authorized CRS, vertical datum, URS, control points, north rotation and acceptance limits.','Project Survey Lead'],
    ['Platforms and versions','Confirm CDE, submission route, worksharing, authoring/export versions and permission matrix.','HATCO BIM Manager'],
    ['Programme and team','Confirm named personnel, milestone/TIDP dates and weekly exchange times.','HATCO Project Manager'],
    ['Conditional uses and handover','Confirm 4D, 5D, existing survey, fabrication, visualization, assets, COBie, tags and retention scope.','HATCO BIM Manager']
  ].map(([subject,decision,owner],i)=>({reference:`HAT-DEC-${String(i+1).padStart(3,'0')}`,subject,decision,owner,dueDate:'',status:'Open'}));
  p.lists.appendices=[['Client EIR / project information standard','PROJECT-EIR'],['Authorized survey / URS and coordinate audit','PROJECT-URS'],['Approved detailed TIDP / MIDP','PROJECT-MIDP']].map(([title,reference])=>({title,reference,status:'Not received',location:''}));
  for(const id of ['fourD','fiveD','existing','fabrication','visualization','assets','cobie','tagging'])p.moduleStates[id]='pending';
  return p;
}
